import sys,os
D=sys.argv[1] if len(sys.argv)>1 else '.'
p=os.path.join(D,'admin.html')
if os.path.exists(p):
    s=open(p,encoding='utf-8').read()
    if '<!--v28-->' not in s:
        s=s.replace("<button onclick=\"dl('entries')\">","<button onclick=\"corr()\"><b>相関レポート（どんな日→どんな夢）</b></button><br><button onclick=\"dl('entries')\">",1)
        s=s.replace('</script>','async function corr(){$(\'msg\').textContent=\'\';const q=new URLSearchParams({kind:\'entries\'});if($(\'from\').value)q.set(\'from\',$(\'from\').value);if($(\'to\').value)q.set(\'to\',$(\'to\').value);\ntry{const r=await fetch(API+\'/v1/admin/export?\'+q,{headers:h()});if(!r.ok)throw new Error(r.status==403?\'トークンが違います\':\'エラー \'+r.status);\nconst txt=(await r.text()).replace(/^\\ufeff/,\'\');const rows=[];let row=[],f=\'\',iq=false;for(let i=0;i<txt.length;i++){const c=txt[i];if(iq){if(c==\'"\'){if(txt[i+1]==\'"\'){f+=\'"\';i++}else iq=false}else f+=c}else if(c==\'"\')iq=true;else if(c==\',\'){row.push(f);f=\'\'}else if(c==\'\\n\'){row.push(f.replace(/\\r$/,\'\'));rows.push(row);row=[];f=\'\'}else f+=c}if(f||row.length){row.push(f);rows.push(row)}\nconst H=rows.shift();const ix=n=>H.indexOf(n);const N=rows.length;if(!N)throw new Error(\'データがまだありません\');\nconst items=r0=>{const o=[];r0[ix(\'words\')].split(\' / \').filter(Boolean).forEach(w=>o.push([\'word\',w]));r0[ix(\'feelings\')].split(\' \').filter(Boolean).forEach(w=>o.push([\'feeling\',w]));return o};\nconst base={};rows.forEach(r0=>new Set(items(r0).map(x=>x.join(\'\\t\'))).forEach(k=>base[k]=(base[k]||0)+1));\nconst skip=new Set([\'day\',\'person\',\'country\',\'age\',\'gender\',\'words\',\'feelings\']);const groups={};\nrows.forEach(r0=>{const fs=[];H.forEach((c,i)=>{if(skip.has(c)||!r0[i])return;if(c==\'links\'){r0[i].split(\' / \').forEach(l=>{const p=l.split(\':\');fs.push([\'link\',p[0]+\':\'+p[1]])})}else r0[i].split(\' \').forEach(v=>fs.push([c,v]))});\n new Set(fs.map(x=>x.join(\'\\t\'))).forEach(g=>{const G=groups[g]||(groups[g]={n:0,p:new Set(),c:{}});G.n++;G.p.add(r0[ix(\'person\')]);new Set(items(r0).map(x=>x.join(\'\\t\'))).forEach(k=>G.c[k]=(G.c[k]||0)+1)})});\nconst out=[];\nObject.entries(groups).sort().forEach(([g,G])=>{if(G.n<5)return;const [fa,ba]=g.split(\'\\t\');Object.entries(G.c).forEach(([k,n])=>{if(n<3)return;const s=n/G.n,b=base[k]/N,l=s/b;if(l<1.2)return;const [t,it]=k.split(\'\\t\');out.push([fa,ba,G.n,G.p.size,t,it,s.toFixed(2),b.toFixed(2),l.toFixed(2)])})});\nout.sort((a,b)=>(+b[8])-(+a[8]));out.unshift([\'factor\',\'band\',\'dreams\',\'people\',\'type\',\'item\',\'share_in_group\',\'share_overall\',\'lift\']);\nconst csv=\'\\ufeff\'+out.map(r1=>r1.map(v=>\'"\'+String(v).replace(/"/g,\'""\')+\'"\').join(\',\')).join(\'\\r\\n\');const a=document.createElement(\'a\');a.href=URL.createObjectURL(new Blob([csv],{type:\'text/csv\'}));a.download=`dream-correlations-${$(\'from\').value||\'all\'}_${$(\'to\').value}.csv`;a.click();\n$(\'ov\').innerHTML+=`<br>相関：${out.length-1}件（夢5件以上の区分・平均の1.2倍以上だけ）`}catch(e){$(\'msg\').textContent=e.message}}\n'+'\n</script>',1)
        s=s.replace('</body>','<!--v28-->\n</body>',1)
        open(p,'w',encoding='utf-8').write(s)
print('v28 patched')
